{
  "name": "属性连接组件",
  "name_en": "Property Connection",
  "manufacturer": "",
  "description": "一个非物理的软件连接组件，用于将两个对象的属性绑定在一起。在实验软件模型或界面中，它可用于维护源对象与目标对象之间的属性同步，并记录源/目标对象标识及对应的属性名。",
  "description_en": "A non-physical software connection component that binds the properties of two objects together. In experiment software models or user interfaces, it is used to maintain synchronization between a source object's property and a target object's property, while storing the source/target specifiers and property names.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭属性连接。",
      "description_en": "Close the property connection."
    },
    {
      "action_name": "auto-source_specifier",
      "description": "获取/设置/定义源对象标识。",
      "description_en": "Get/set/define the source object specifier."
    },
    {
      "action_name": "auto-target_specifier",
      "description": "获取/设置/定义目标对象标识。",
      "description_en": "Get/set/define the target object specifier."
    },
    {
      "action_name": "auto-source_property",
      "description": "获取/设置/定义源属性名称。",
      "description_en": "Get/set/define the source property name."
    },
    {
      "action_name": "auto-target_property",
      "description": "获取/设置/定义目标属性名称。",
      "description_en": "Get/set/define the target property name."
    }
  ],
  "tag_hints": [
    "property binding",
    "object synchronization",
    "experiment software model",
    "UI property linkage",
    "source target mapping"
  ]
}

